using Microsoft.EntityFrameworkCore;
using SiapSD.Cognitive.Domain;
namespace SiapSD.Cognitive.Infrastructure;
public class SiapSDDbContext(DbContextOptions<SiapSDDbContext> options) : DbContext(options) {
 public DbSet<Child> Children => Set<Child>(); public DbSet<CognitiveDomain> CognitiveDomains => Set<CognitiveDomain>(); public DbSet<Subtest> Subtests => Set<Subtest>(); public DbSet<Question> Questions => Set<Question>(); public DbSet<QuestionOption> QuestionOptions => Set<QuestionOption>(); public DbSet<AssessmentBlueprint> AssessmentBlueprints => Set<AssessmentBlueprint>(); public DbSet<AssessmentBlueprintItem> AssessmentBlueprintItems => Set<AssessmentBlueprintItem>(); public DbSet<AssessmentSession> AssessmentSessions => Set<AssessmentSession>(); public DbSet<AssessmentResponse> AssessmentResponses => Set<AssessmentResponse>(); public DbSet<AssessmentDomainScore> AssessmentDomainScores => Set<AssessmentDomainScore>();
 protected override void OnModelCreating(ModelBuilder b) { base.OnModelCreating(b); foreach(var e in b.Model.GetEntityTypes()) foreach(var p in e.GetProperties().Where(p=>p.ClrType==typeof(decimal))) p.SetColumnType("numeric(12,2)"); b.Entity<CognitiveDomain>().HasIndex(x=>x.Code).IsUnique(); b.Entity<Subtest>().HasIndex(x=>new{x.CognitiveDomainId,x.Code}).IsUnique(); b.Entity<Question>().HasIndex(x=>x.Code).IsUnique(); b.Entity<AssessmentResponse>().HasIndex(x=>new{x.AssessmentSessionId,x.QuestionId}).IsUnique(); b.Entity<Question>().HasMany(x=>x.Options).WithOne().HasForeignKey(x=>x.QuestionId).OnDelete(DeleteBehavior.Cascade); b.Entity<AssessmentSession>().HasMany(x=>x.Responses).WithOne().HasForeignKey(x=>x.AssessmentSessionId).OnDelete(DeleteBehavior.Cascade); }
}
